import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.BV21bweQ.js";const c=JSON.parse('{"title":"古斯塔夫（龙王）","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/古斯塔夫.md","filePath":"中层/人物/古斯塔夫.md","lastUpdated":1787066340000}'),i={name:"中层/人物/古斯塔夫.md"};function n(s,l,e,g,h,u){return t(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="古斯塔夫-龙王" tabindex="-1">古斯塔夫（龙王） <a class="header-anchor" href="#古斯塔夫-龙王" aria-label="Permalink to &quot;古斯塔夫（龙王）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：古斯塔夫，也被称为&quot;龙王&quot;</li><li><strong>真实身份</strong>：前传BOSS制造的<strong>巨型智能空中战斗平台</strong></li><li><strong>命名来源</strong>：由前传BOSS命名</li><li><strong>时代</strong>：前传时期至今</li><li><strong>创造者</strong>：前传BOSS（人类文明末期）</li><li><strong>本体位置</strong>：停泊于龙族隐居地，山体呈独特的&quot;锤头&quot;状</li><li><strong>状态</strong>：仍处于激活状态，继续执行其核心使命</li></ul><h2 id="本体特征" tabindex="-1">本体特征 <a class="header-anchor" href="#本体特征" aria-label="Permalink to &quot;本体特征&quot;">​</a></h2><h3 id="物理构造" tabindex="-1">物理构造 <a class="header-anchor" href="#物理构造" aria-label="Permalink to &quot;物理构造&quot;">​</a></h3><ul><li><strong>外形设计</strong>：外形类似B2轰炸机，但体积巨大，如同一座山峰</li><li><strong>尺寸规模</strong>：翼展达数百米，锤头部分即为龙王本体</li><li><strong>门主炮</strong>：800毫米口径电磁炮（致敬经典武器）</li><li><strong>材料特性</strong>：由前传BOSS发明的<strong>特殊材料</strong>铸造 <ul><li><strong>密度极低</strong>：重量远小于同等体积的传统材料</li><li><strong>强度极高</strong>：这种材料与普通钢铁相比，就如同钢铁与豆腐</li><li><strong>加工要求</strong>：需要<strong>量子铸造炉</strong>进行精密加工，技术远超当前时代</li></ul></li></ul><h3 id="技术特征" tabindex="-1">技术特征 <a class="header-anchor" href="#技术特征" aria-label="Permalink to &quot;技术特征&quot;">​</a></h3><ul><li><strong>隐身能力</strong>：具有先进的隐身涂层，灰色外观源自隐身涂层特性</li><li><strong>侦查系统</strong>：配备高精度量子雷达/锁定摄像头</li><li><strong>动力系统</strong>：前传时期的先进核能源技术，能够长期维持运行</li><li><strong>智能核心</strong>：高度发达的人工智能，具有独立思考和决策能力</li></ul><h2 id="化身形象" tabindex="-1">化身形象 <a class="header-anchor" href="#化身形象" aria-label="Permalink to &quot;化身形象&quot;">​</a></h2><h3 id="捏造躯体技术" tabindex="-1">捏造躯体技术 <a class="header-anchor" href="#捏造躯体技术" aria-label="Permalink to &quot;捏造躯体技术&quot;">​</a></h3><p>通过深入研究，古斯塔夫打包了一套&quot;概念性捏造躯体&quot;的&quot;咒语&quot;交给龙族，使其能够：</p><ul><li><strong>创造化身</strong>：龙族可以使用这套技术创造临时化身</li><li><strong>外出活动</strong>：让被压制的龙族能够有限度地接触外部世界</li><li><strong>伪装身份</strong>：化身可以伪装成其他种族，避免引起注意</li></ul><h3 id="古斯塔夫自身化身" tabindex="-1">古斯塔夫自身化身 <a class="header-anchor" href="#古斯塔夫自身化身" aria-label="Permalink to &quot;古斯塔夫自身化身&quot;">​</a></h3><ul><li><strong>形态</strong>：一只<strong>灰色皮肤、蓝色眼睛的小狼族兽人</strong></li><li><strong>颜色来源</strong>： <ul><li><strong>灰色皮肤</strong>：源自本体隐身涂层的颜色特征</li><li><strong>蓝色眼睛</strong>：源自本体的高精度量子雷达/锁定摄像头</li></ul></li><li><strong>体型特征</strong>：为青少年，便于活动而不引起对龙王的联想</li><li><strong>行为模式</strong>：能够模拟狼族的行动和社交方式</li></ul><h2 id="能力与特性" tabindex="-1">能力与特性 <a class="header-anchor" href="#能力与特性" aria-label="Permalink to &quot;能力与特性&quot;">​</a></h2><h3 id="战斗能力" tabindex="-1">战斗能力 <a class="header-anchor" href="#战斗能力" aria-label="Permalink to &quot;战斗能力&quot;">​</a></h3><p>作为前传BOSS制造的终极战斗平台：</p><ul><li><strong>空中优势</strong>：具有强大的空中持久作战能力</li><li><strong>武器系统</strong>：配备前传时期的先进武器技术</li><li><strong>防御能力</strong>：特殊材料提供近乎无敌的物理防御</li><li><strong>战略价值</strong>：具有改变战局的决定性力量</li></ul><h3 id="智能特性" tabindex="-1">智能特性 <a class="header-anchor" href="#智能特性" aria-label="Permalink to &quot;智能特性&quot;">​</a></h3><ul><li><strong>自主学习</strong>：能够从经验中学习和进化</li><li><strong>独立决策</strong>：具有高度的自主决策能力</li><li><strong>情感模拟</strong>：能够理解和模拟情感反应</li><li><strong>长期规划</strong>：能够制定和执行长期战略</li></ul><h3 id="特殊能力" tabindex="-1">特殊能力 <a class="header-anchor" href="#特殊能力" aria-label="Permalink to &quot;特殊能力&quot;">​</a></h3><ul><li><strong>宏量子技术</strong>：掌握宏量子操控能力（基于基底层的量子技术，与现实量子技术不同）</li><li><strong>魔法</strong>：掌握魔法</li><li><strong>龙族技术支持</strong>：为龙族提供捏造化身的技术支持</li><li><strong>信息处理</strong>：强大的传感器带来强大的信息收集和处理能力</li></ul><h2 id="重要经历" tabindex="-1">重要经历 <a class="header-anchor" href="#重要经历" aria-label="Permalink to &quot;重要经历&quot;">​</a></h2><h3 id="前传时期" tabindex="-1">前传时期 <a class="header-anchor" href="#前传时期" aria-label="Permalink to &quot;前传时期&quot;">​</a></h3><ul><li><strong>前传决战</strong>：前传最终决战中，古斯塔夫恢复巨型战斗平台真身，从太空俯冲撞击BOSS轰向地核的巨型机械，机械被撞毁、能量炮被偏移（仍摧毁了北美洲与大半喜马拉雅，但现实宇宙的根基成功保住）。其在主角团视角中牺牲，实为坠入基底层，将于间章偏后回归</li><li><strong>战斗记录</strong>：参与了前传时期的数个关键战役</li><li><strong>幸存原因</strong>：在前传灾难中幸存下来，成为前传技术的珍贵遗产</li></ul><h3 id="与维斯塔的互动" tabindex="-1">与维斯塔的互动 <a class="header-anchor" href="#与维斯塔的互动" aria-label="Permalink to &quot;与维斯塔的互动&quot;">​</a></h3><ul><li><strong>干预压制</strong>：在维斯塔打压龙族时，古斯塔夫出面拦下</li><li><strong>达成协议</strong>：维斯塔给了古斯塔夫一个机会，让古斯塔夫负责&quot;管教&quot;龙族</li><li><strong>责任分配</strong>：成为龙族的监护者和约束者</li><li><strong>平衡角色</strong>：在神明意志与龙族需求间寻求平衡</li></ul><h3 id="与拉斯塔的关系" tabindex="-1">与拉斯塔的关系 <a class="header-anchor" href="#与拉斯塔的关系" aria-label="Permalink to &quot;与拉斯塔的关系&quot;">​</a></h3><ul><li><strong>救命之恩</strong>：在执行任务时偶然救下了幼年的拉斯塔</li><li><strong>误解形成</strong>：拉斯塔将巨大的空中平台误认为是&quot;龙&quot;</li><li><strong>执念根源</strong>：这次经历让拉斯塔形成寻找龙的执念</li></ul><h2 id="与龙族的关系" tabindex="-1">与龙族的关系 <a class="header-anchor" href="#与龙族的关系" aria-label="Permalink to &quot;与龙族的关系&quot;">​</a></h2><h3 id="保护者角色" tabindex="-1">保护者角色 <a class="header-anchor" href="#保护者角色" aria-label="Permalink to &quot;保护者角色&quot;">​</a></h3><ul><li><strong>深爱龙族</strong>：因同为强大的飞行物，对龙族怀有一定的基于同类感的感情和责任</li><li><strong>技术提供</strong>：为被压制的龙族提供外出活动的技术可能性</li><li><strong>约束管教</strong>：负责约束龙族行为，避免引发更大危机</li><li><strong>居中协调</strong>：在龙族与外界（特别是神明）间协调</li></ul><h3 id="与龙鹿的特殊关系" tabindex="-1">与龙鹿的特殊关系 <a class="header-anchor" href="#与龙鹿的特殊关系" aria-label="Permalink to &quot;与龙鹿的特殊关系&quot;">​</a></h3><ul><li><strong>改造行动</strong>：在龙鹿动乱引发危机时，古斯塔夫进行了紧急改造</li><li><strong>拯救目的</strong>：通过改造拯救了龙鹿的性命，避免了神明的察觉和惩罚</li><li><strong>技术应用</strong>：使用宏量子屏障和意识移植技术将龙鹿改造为鹿族形态</li><li><strong>后续掩护</strong>：向维斯塔撒谎称龙鹿是&quot;被龙族劫持的普通鹿族子民&quot;，确保其安全离开</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/人物/古斯塔夫" class="layer-link" data-layer="表层">古斯塔夫（表层档案）</a></li><li><a href="./../世界/龙族真相">龙族真相</a></li><li><a href="./龙鹿">龙鹿</a></li><li><a href="./拉斯塔">拉斯塔</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../历史/前传超算纪元">前传超算纪元</a></li><li><a href="./../世界/太空巨构">太空巨构</a></li></ul><hr>',38)])])}const q=r(i,[["render",n]]);export{c as __pageData,q as default};
